mapper.select:
select l.order_line_id orderLineId,l.license_id licenseId from w18_paid_license l
join oms_order o on o.id=l.order_id and o.member_id=l.buyer_member_id and o.del_flag=0 and o.biz_type='workshop_module_v1'
join ums_member buyer on buyer.id=l.buyer_member_id and buyer.status=1 and buyer.del_flag=0
where l.buyer_member_id=#{actor}
and l.order_line_id < #{before}
order by l.order_line_id desc limit 51
